<section class="page-hero page-hero-compact"><div class="container"><span class="eyebrow">INSTITUTION SPACE</span><h1><?= e($institution['name']) ?></h1><p>Share relevant opportunities and announcements with your campus community.</p></div></section>
<section class="section"><div class="container">
    <div class="dashboard-summary"><article class="summary-card"><span>Students on platform</span><strong><?= e($stats['students']) ?></strong></article><article class="summary-card summary-blue"><span>Published opportunities</span><strong><?= e($stats['opportunities']) ?></strong></article><article class="summary-card summary-plum"><span>Applications received</span><strong><?= e($stats['applications']) ?></strong></article></div>
    <section class="panel organization-panel"><div class="panel-heading"><div><span class="eyebrow">INSTITUTION PROFILE</span><h2>Update institution information</h2></div></div><form class="form-stack compact-form" method="post" action="<?= e(pageUrl('institution')) ?>"><?= formToken() ?><input type="hidden" name="action" value="update_institution_profile"><div class="field-row"><label class="field"><span>Location</span><input name="location" maxlength="160" value="<?= e($institution['location'] ?? '') ?>"></label><label class="field"><span>Website</span><input name="website" type="url" maxlength="255" value="<?= e($institution['website'] ?? '') ?>"></label></div><label class="field"><span>Contact email</span><input name="contact_email" type="email" maxlength="190" value="<?= e($institution['contact_email'] ?? '') ?>"></label><label class="field"><span>Description</span><textarea name="description" rows="3" maxlength="4000"><?= e($institution['description'] ?? '') ?></textarea></label><button class="button button-outline" type="submit">Save institution profile</button></form></section>
