    <div class="panel"><?php if ($opportunities === []): ?><div class="empty-small"><p>No published institution opportunities yet.</p></div><?php else: ?><div class="opportunity-grid"><?php foreach ($opportunities as $item): ?><?= opportunityCard($item) ?><?php endforeach; ?></div><?php endif; ?></div>
    <div class="admin-two-column dashboard-section-heading"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">CAMPUS UPDATES</span><h2>Announcements</h2></div></div><form class="form-stack compact-form" method="post" action="<?= e(pageUrl('institution')) ?>"><?= formToken() ?><input type="hidden" name="action" value="create_announcement"><label class="field"><span>Title</span><input name="title" maxlength="180" required></label><label class="field"><span>Message</span><textarea name="body" rows="4" maxlength="5000" required></textarea></label><label class="checkbox-field"><input type="checkbox" name="is_published" value="1"><span>Publish now</span></label><button class="button button-outline" type="submit">Save announcement</button></form></section>
        <section class="panel"><div class="panel-heading"><div><span class="eyebrow">RECENT ANNOUNCEMENTS</span><h2>Campus notices</h2></div></div><?php if ($announcements === []): ?><div class="empty-small"><p>No announcements have been published.</p></div><?php else: ?><div class="announcement-list"><?php foreach ($announcements as $announcement): ?><article><h3><?= e($announcement['title']) ?></h3><p><?= nl2br(e($announcement['body'])) ?></p><time><?= $announcement['is_published'] ? 'Published · ' : 'Draft · ' ?><?= e(date('M j, Y', strtotime($announcement['published_at'] ?? $announcement['created_at']))) ?></time><form method="post" action="<?= e(pageUrl('institution')) ?>"><?= formToken() ?><input type="hidden" name="action" value="toggle_announcement"><input type="hidden" name="announcement_id" value="<?= e($announcement['id']) ?>"><button class="button button-text"><?= $announcement['is_published'] ? 'Unpublish' : 'Publish' ?></button></form></article><?php endforeach; ?></div><?php endif; ?></section></div>
</div></section>
